import {
  handleHttpError,
  enableNotifications,
  checkInput,
  unsubscribeNotifications,
} from '/static/js/common/functions.prod.js';
import {
  showErrorMessage,
  showSuccessMessage,
} from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  NProgress.done();
  let t = $('[name="csrftoken"]')[0].content;
  ($(document).on('htmx:afterSwap', function () {
    (checkInput(), NProgress.done());
  }),
    window.addEventListener('popstate', () => {
      (NProgress.start(),
        setTimeout(() => {
          NProgress.done();
        }, 1e3));
    }));
  let e = new URLSearchParams(window.location.search).get('view_page');
  (e &&
    (NProgress.start(),
    htmx.ajax('GET', `?page=${e}`, {
      target: '.mainContent',
      swap: 'replace',
    })),
    document.body.addEventListener('htmx:responseError', function (t) {
      handleHttpError(t.detail.xhr.status);
    }),
    $('body').on('click', '#notifications.checkbox', async function () {
      $(this).prop('checked')
        ? await enableNotifications()
        : (showErrorMessage(
            gettext('Notifications Silenced'),
            gettext('You will not receive notifications')
          ),
          unsubscribeNotifications());
    }),
    $('body').on('click', '#email.checkbox', function () {}),
    $('body').on('click', 'button', function () {
      let e = $('.inputHolder').find('input');
      if (1 == e.length) {
        let o = e.attr('id'),
          s = e.val().trim(),
          n = e.data('edit-name');
        if (0 == s.length)
          return void showErrorMessage(
            gettext('Empty Field'),
            gettext('Kindly Fill in the Blank Space')
          );
        (n &&
          n.length &&
          $.ajax({
            type: 'POST',
            headers: { 'X-CSRFToken': t },
            url: '?action=edit_personal_info',
            data: JSON.stringify({ editName: o, editValue: s }),
            success: function (t) {
              if (t.status) {
                const t = interpolate(
                  gettext('You have updated your %(editName)s'),
                  { ediName: n },
                  !0
                );
                return void showSuccessMessage(gettext('Details Changed'), t);
              }
              showErrorMessage(
                gettext('Details Not Changed'),
                gettext('An error occurred try again.')
              );
            },
          }),
          'login_password' == o &&
            $.ajax({
              type: 'POST',
              url: '?action=confirm_password',
              headers: { 'X-CSRFToken': t },
              data: JSON.stringify({ password: s }),
              success: function (t) {
                if (t.status)
                  return (
                    showSuccessMessage(
                      gettext('Password Confirmed'),
                      gettext('Enter your new password to change it.')
                    ),
                    void $('.mainContent').empty().append(t.html)
                  );
                t.logout
                  ? (showErrorMessage(
                      gettext('Logging you out'),
                      gettext('Too many password attempts.')
                    ),
                    NProgress.start(),
                    $('button').prop('disabled', !0),
                    setTimeout(() => {
                      window.location.reload();
                    }, 2e3))
                  : showErrorMessage(
                      gettext('Password Failed'),
                      gettext(
                        'You will be logged out after 3 incorrect attempts.'
                      )
                    );
              },
            }));
      } else if (2 == e.length) {
        let o = e.first(),
          s = e.last();
        o.val().trim() == s.val().trim() &&
          $.ajax({
            type: 'POST',
            headers: { 'X-CSRFToken': t },
            url: '?action=change_password&verification=True',
            data: JSON.stringify({ password: o.val().trim() }),
            success: function (t) {
              t.status
                ? showSuccessMessage(
                    gettext('Password Changed'),
                    gettext('Kindly log in with your new password')
                  ).done(function () {
                    window.location.reload();
                  })
                : showErrorMessage();
            },
          });
      }
    }));
  let o = !1;
  ($('main').on('click', '.logout_content_button', function () {
    o
      ? $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': t },
          url: '?action=logout',
          success: function (t) {
            t.status
              ? (showSuccessMessage('Logged Out', 'Refreshing your page'),
                setTimeout(() => {
                  window.location.reload();
                }, 2e3))
              : showErrorMessage('Could Not Log Out', 'Kindly Try again.');
          },
        })
      : (showErrorMessage(
          gettext('Are you sure?'),
          gettext('Kindly click Logout again to confirm')
        ),
        (o = !0));
  }),
    $('main').on('click', '#join_smst_pro_button', function () {
      $.ajax({
        type: 'GET',
        url: '?action=init_paystack',
        success: function (t) {
          let e = t.response.data.access_code;
          new PaystackPop().resumeTransaction(e);
        },
      });
    }),
    $('main').on('click', '#cancel_join_smst_pro', function () {
      history.back();
    }));
});
